#!/usr/bin/env python3
"""Qualification runner -- GENERATED by receipt-provenance-unification-pack.

Do not hand-edit. Regenerate with `ggen sync run` from the pack's ontology.ttl.

Chicago style: real receipt fixtures, the real generated validator in a real
subprocess, real git repositories. No mocks.

1. Every rp:QualificationSuite directory: pos-*.json must exit 0, neg-*.json
   must exit 1 and print a broken_term matching the suite's pattern; no output
   may contain a traceback. Suites with rp:fleetParity also require the exit
   code of ~/.claude/dfcm/validate_receipt.py (skipped, visibly, when absent).
2. A throwaway git repository under the system temp dir (removed afterwards)
   exercises the git-notes location and the default profile's local-directory
   identity probe, positively and negatively.
3. Coverage: every rp:ResolutionKind in the ontology must be observed both
   passing ("probe <kind> ok") and failing ("probe <kind> failed").

Usage: qualification_runner.py [--repo-map owner/repo=path ...]
Exit 0 = qualified, 1 = a case failed, 2 = usage error.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import subprocess
import sys
import tempfile

PACK = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
VALIDATOR = os.path.join(PACK, "generated", "unified_receipt_validator.py")
FLEET_VALIDATOR = os.path.join(os.path.expanduser("~"), ".claude", "dfcm", "validate_receipt.py")

SUITES: list[dict] = [
    {"dir": "qualification/fixtures/dfcm_fleet_v1", "args": "--contract=dfcm_fleet_v1".split(" "), "fleet_parity": True, "uses_repo_map": False, "term_pattern": "R_missing_|admission_vacuous", "requires_repo": ""},
    {"dir": "qualification/fixtures/durable", "args": "--contract=dfcm_fleet_v1 --require-durable".split(" "), "fleet_parity": False, "uses_repo_map": True, "term_pattern": "R_missing_identity|R_missing_replay", "requires_repo": "seanchatmangpt/xaas"},
    {"dir": "qualification/fixtures/durable_standing", "args": "--contract=dfcm_fleet_v1 --require-durable".split(" "), "fleet_parity": False, "uses_repo_map": True, "term_pattern": "R_missing_standing", "requires_repo": "seanchatmangpt/xaas"},
]

RESOLUTION_KINDS: list[str] = [
    "ancestor_of",
    "blob_at_commit",
    "notes_object",
    "subject_commit",
]

PROBE_OK = re.compile(r"probe (\w+) ok")
PROBE_FAILED = re.compile(r"probe (\w+) failed")
NOTES_SLUG = "qualification/notes"


def run(argv: list[str]):
    proc = subprocess.run(argv, cwd=PACK, capture_output=True)
    out = (proc.stdout + proc.stderr).decode("utf-8", "replace")
    return proc.returncode, out


class Tally:
    def __init__(self) -> None:
        self.passed, self.failed, self.skipped = 0, [], []
        self.kinds_ok, self.kinds_failed = set(), set()

    def observe(self, out: str) -> None:
        self.kinds_ok.update(PROBE_OK.findall(out))
        self.kinds_failed.update(PROBE_FAILED.findall(out))

    def check(self, label: str, code: int, out: str, expected: int, term_pattern: str) -> None:
        self.observe(out)
        problems = []
        if code != expected:
            problems.append(f"exit {code} != expected {expected}")
        if "Traceback" in out:
            problems.append("traceback in output")
        if expected == 1 and term_pattern and not re.search(term_pattern, out):
            problems.append(f"no broken_term matching {term_pattern}")
        if problems:
            self.failed.append(f"{label}: {'; '.join(problems)}\n{out}")
            print(f"FAIL {label}: {'; '.join(problems)}")
        else:
            self.passed += 1
            print(f"PASS {label} (exit {code})")


def repo_map_args(repo_map: dict) -> list[str]:
    args = []
    for slug, where in sorted(repo_map.items()):
        args += ["--repo-map", f"{slug}={where}"]
    return args


def run_suites(tally: Tally, repo_map: dict) -> None:
    fleet_present = os.path.isfile(FLEET_VALIDATOR)
    for suite in SUITES:
        directory = os.path.join(PACK, suite["dir"])
        if suite["requires_repo"] and suite["requires_repo"] not in repo_map:
            tally.skipped.append(f"{suite['dir']}: needs --repo-map {suite['requires_repo']}=<path>")
            print(f"SKIP {suite['dir']}: needs --repo-map {suite['requires_repo']}=<path>")
            continue
        for name in sorted(os.listdir(directory)):
            if not name.endswith(".json"):
                continue
            rel = os.path.join(suite["dir"], name)
            if name.startswith("pos-"):
                expected = 0
            elif name.startswith("neg-"):
                expected = 1
            else:
                tally.failed.append(f"{rel}: fixture name must start with pos- or neg-")
                print(f"FAIL {rel}: fixture name must start with pos- or neg-")
                continue
            argv = [sys.executable, VALIDATOR, rel, *suite["args"]]
            if suite["uses_repo_map"]:
                argv += repo_map_args(repo_map)
            code, out = run(argv)
            tally.check(rel, code, out, expected, suite["term_pattern"])
            if suite["fleet_parity"]:
                if not fleet_present:
                    tally.skipped.append(f"{rel}: parity (validate_receipt.py absent)")
                    continue
                fleet_code, fleet_out = run([sys.executable, FLEET_VALIDATOR, rel])
                if "ModuleNotFoundError" in fleet_out:
                    tally.skipped.append(f"{rel}: parity (validate_receipt.py cannot import its dependencies)")
                    continue
                tally.check(f"{rel} [parity with validate_receipt.py]", fleet_code, fleet_out, code, "")


def git(repo: str, *args: str) -> str:
    proc = subprocess.run(
        ["git", "-C", repo, "-c", "user.name=qualification", "-c", "user.email=qualification@example.invalid",
         "-c", "commit.gpgsign=false", "-c", "core.hooksPath=/dev/null", *args],
        capture_output=True,
    )
    if proc.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)}: {proc.stderr.decode('utf-8', 'replace').strip()}")
    return proc.stdout.decode("utf-8", "replace").strip()


def receipt(repo: str, subject_sha: str, durable_location: str) -> dict:
    return {
        "identity": {"subject": "qualification", "repo": repo, "subject_sha": subject_sha, "base_sha": subject_sha},
        "authority": {"ceiling": "OBSERVE", "grant": "NONE", "actor": "qualification_runner"},
        "consequence": {"commits": [], "files_changed": [], "remote_effects": []},
        "replay": {
            "commands": [{"cmd": "qualification fixture", "cwd": ".", "exit": 0}],
            "durable_location": durable_location,
        },
        "standing": {"value": "UNKNOWN", "derived_from": "qualification fixture"},
    }


def run_git_repo_cases(tally: Tally) -> None:
    scratch = tempfile.mkdtemp(prefix="rpv-qualification-")
    try:
        repo = os.path.join(scratch, "repo")
        os.mkdir(repo)
        git(repo, "init", "-q")
        for name in ("first", "second"):
            with open(os.path.join(repo, f"{name}.txt"), "w", encoding="utf-8") as fh:
                fh.write(name + "\n")
            git(repo, "add", f"{name}.txt")
            git(repo, "commit", "-q", "-m", name)
        second = git(repo, "rev-parse", "HEAD")
        first = git(repo, "rev-parse", "HEAD~1")
        git(repo, "notes", "--ref=refs/notes/receipts", "add", "-m", "receipt", first)
        mapping = ["--repo-map", f"{NOTES_SLUG}={repo}"]
        durable = ["--contract=dfcm_fleet_v1", "--require-durable", *mapping]
        cases = [
            ("git-notes: note on the subject", receipt(NOTES_SLUG, first, f"git-notes:refs/notes/receipts@{first}"), durable, 0, ""),
            ("git-notes: no note on that commit", receipt(NOTES_SLUG, second, f"git-notes:refs/notes/receipts@{second}"), durable, 1, "R_missing_replay"),
            ("git-notes: noted commit is not a descendant of the subject", receipt(NOTES_SLUG, second, f"git-notes:refs/notes/receipts@{first}"), durable, 1, "R_missing_replay"),
            ("default profile: local directory holds the subject", receipt(repo, first, "anything"), ["--contract=dfcm_fleet_v1"], 0, ""),
            ("default profile: local directory lacks the subject", receipt(repo, "0" * 40, "anything"), ["--contract=dfcm_fleet_v1"], 1, "R_missing_identity"),
        ]
        for index, (label, doc, args, expected, term) in enumerate(cases):
            path = os.path.join(scratch, f"case-{index}.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump(doc, fh)
            code, out = run([sys.executable, VALIDATOR, path, *args])
            tally.check(f"git repo case: {label}", code, out, expected, term)
    finally:
        shutil.rmtree(scratch, ignore_errors=True)


def main(argv: list[str]) -> int:
    repo_map: dict[str, str] = {}
    i = 1
    while i < len(argv):
        name, eq, val = argv[i].partition("=")
        if name != "--repo-map":
            print(f"unknown argument {argv[i]}\nusage: qualification_runner.py [--repo-map owner/repo=path ...]", file=sys.stderr)
            return 2
        if not eq:
            if i + 1 >= len(argv):
                print("--repo-map needs a value", file=sys.stderr)
                return 2
            i += 1
            val = argv[i]
        slug, sep, where = val.partition("=")
        if not sep or not slug or not where:
            print(f"--repo-map expects owner/repo=path, got {val!r}", file=sys.stderr)
            return 2
        repo_map[slug] = where
        i += 1

    tally = Tally()
    run_suites(tally, repo_map)
    run_git_repo_cases(tally)
    missing_ok = [k for k in RESOLUTION_KINDS if k not in tally.kinds_ok]
    missing_failed = [k for k in RESOLUTION_KINDS if k not in tally.kinds_failed]
    if missing_ok or missing_failed:
        tally.failed.append(f"coverage: never passed {missing_ok}, never failed {missing_failed}")
        print(f"FAIL coverage: never passed {missing_ok}, never failed {missing_failed}")
    else:
        print(f"PASS coverage: every resolution kind observed passing and failing ({', '.join(RESOLUTION_KINDS)})")
    for skip in tally.skipped:
        print(f"SKIP {skip}")
    verdict = "PASS" if not tally.failed else "FAIL"
    print(f"QUALIFICATION {verdict} passed={tally.passed} failed={len(tally.failed)} skipped={len(tally.skipped)}")
    return 0 if not tally.failed else 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
